616	/// Generate value candidates for the segment under the cursor of a
617	/// delimiter-separated multi-value option.
618	///
619	/// `prior_segments` is the number of segments already closed by earlier shell
620	/// words; `prior_used` are their literal values, suppressed from the result so
621	/// an already selected value is not offered a second time.  Candidates cover
622	/// only the current shell word, so `prefix` from closed segments is limited to
623	/// the current word as well.
624	///
625	/// `Ok` carries the candidates; `Err(())` marks an illegal segment position
626	/// (an empty segment or a segment past the accepted number of values).
627	fn complete_segment_value(
628	    value: &OsStr,
629	    opt: &clap::Arg,
630	    prior_segments: usize,
631	    prior_used: &[&OsStr],
632	    arg_index: usize,
633	    current_dir: Option<&std::path::Path>,
634	) -> Result<Vec<CompletionCandidate>, ()> {
635	    let Some(cursor) = cursor_delimited(opt, value, prior_segments)? else {
636	        // Not a bounded delimiter option: keep the legacy whole-word
637	        // completion (its own `rsplit_delimiter` handles single-value args).
638	        return Ok(complete_arg_value(
639	            value.to_str().ok_or(value),
640	            opt,
641	            current_dir,
642	            arg_index,
643	        ));
644	    };
645	
646	    let mut used: Vec<&OsStr> = prior_used.to_vec();
647	    used.extend(cursor.closed.iter().copied());
648	
649	    let mut values = complete_arg_value(
650	        Ok(cursor.current.to_str().ok_or(())?),
651	        opt,
652	        current_dir,
653	        arg_index,
654	    );
655	    // An already closed segment stays selected and must not reappear.
656	    values.retain(|comp| !used.iter().any(|u| *u == comp.get_value()));
657	    if !cursor.prefix.is_empty() {
658	        values = values
659	            .into_iter()
660	            .map(|comp| comp.add_prefix(cursor.prefix))
661	            .collect();
662	    }
663	    Ok(values)
664	}
