666	/// Completion at a space-separated option value word tracked by `state`.
667	fn complete_separate_opt_value(
668	    value: Result<&str, &OsStr>,
669	    state: &OptState<'_>,
670	    current_dir: Option<&std::path::Path>,
671	) -> Result<Vec<CompletionCandidate>, ()> {
672	    let value_os = match value {
673	        Ok(value) => OsStr::new(value),
674	        Err(value_os) => value_os,
675	    };
676	    let used: Vec<&OsStr> = state.used.iter().map(OsString::as_os_str).collect();
677	    complete_segment_value(
678	        value_os,
679	        state.opt,
680	        state.used.len(),
681	        &used,
682	        state.word.saturating_sub(1),
683	        current_dir,
684	    )
685	}
