687	/// Complete the inline value carried by the cursor's option word.
688	///
689	/// This covers `--name=value` as well as short clusters with an attached
690	/// value, e.g. `-ovalue` and `-o=value` (including leading flags, `-abovalue`).
691	/// It returns the option's value candidates, re-prefixed with the exact
692	/// option spelling, when the cursor is inside such a value.  The whole word is
693	/// consumed by its option: nothing after `=` or past the taking flag takes
694	/// part in option-name, subcommand or positional completion, and the word is
695	/// not yet part of the conflict set.
696	///
697	/// A bare `--name`/`-o` whose value is still a separate word completes
698	/// normally, as does an unknown long name, a recognized option that takes no
699	/// value and anything else that cannot be recognized: `None` preserves the
700	/// existing failure semantics rather than guessing a split.
701	///
702	/// `Some(Err(()))` means the recognized word is an illegal value position for
703	/// a bounded delimiter option (an empty segment or a segment past the accepted
704	/// number of values) and must yield "no completion generated".
705	fn complete_inline_option_value(
706	    arg: &clap_lex::ParsedArg<'_>,
707	    cmd: &clap::Command,
708	    current_dir: Option<&std::path::Path>,
709	    disabled: &HashSet<Id>,
710	) -> Option<Result<Vec<CompletionCandidate>, ()>> {
711	    if let Some((flag, value)) = arg.to_long() {
712	        let flag = flag.ok()?;
713	        // A bare `--name` has no attached value and is completed as an option name.
714	        let value = value?;
715	        let opt = cmd.get_arguments().find(|a| {
716	            a.get_long_and_visible_aliases()
717	                .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
718	        })?;
719	        if !opt.get_num_args().expect("built").takes_values() {
720	            return None;
721	        }
722	        if disabled.contains(opt.get_id()) {
723	            return Some(Ok(Vec::new()));
724	        }
725	        let prefix = format!("--{flag}=");
726	        return Some(
727	            complete_segment_value(value, opt, 0, &[], 0, current_dir).map(|values| {
728	                values
729	                    .into_iter()
730	                    .map(|comp| comp.add_prefix(&prefix))
731	                    .collect()
732	            }),
733	        );
734	    }
735	
736	    let short = arg.to_short()?;
737	    if short.is_negative_number() {
738	        return None;
739	    }
740	    let (leading_flags, opt, mut value_flags, _) = parse_shortflags(cmd, short);
741	    let opt = opt?;
742	
743	    // Detect an attached value: once the cluster reaches its value-taking
744	    // flag, everything left is the value, optionally introduced by `=`.  With
745	    // no remainder and no `=` (`-o`), the word is left to the regular option
746	    // completion, which already offers inline values.
747	    let mut peek = value_flags.clone();
748	    let has_equal = matches!(peek.next_flag(), Some(Ok('=')));
749	    if !has_equal && value_flags.is_empty() {
750	        return None;
751	    }
752	    if has_equal {
753	        // Consume the `=` so the remainder is the bare value (possibly empty
754	        // for `-o=`), matching the space-separated empty-value position.
755	        value_flags.next_flag();
756	    }
757	    if disabled.contains(opt.get_id()) {
758	        return Some(Ok(Vec::new()));
759	    }
760	    let value = value_flags.next_value_os().unwrap_or(OsStr::new(""));
761	    let sep = if has_equal { "=" } else { "" };
762	    let prefix = format!("-{leading_flags}{sep}");
763	    Some(
764	        complete_segment_value(value, opt, 0, &[], 0, current_dir).map(|values| {
765	            values
766	                .into_iter()
767	                .map(|comp| comp.add_prefix(&prefix))
768	                .collect()
769	        }),
770	    )
771	}
