773	fn complete_option(
774	    arg: &clap_lex::ParsedArg<'_>,
775	    cmd: &clap::Command,
776	    current_dir: Option<&std::path::Path>,
777	    disabled: &HashSet<Id>,
778	) -> Vec<CompletionCandidate> {
779	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
780	    let mut completions = Vec::<CompletionCandidate>::new();
781	    if arg.is_empty() {
782	        completions.extend(longs_and_visible_aliases(cmd, disabled));
783	        completions.extend(hidden_longs_aliases(cmd, disabled));
784	
785	        let dash_or_arg = if arg.is_empty() {
786	            "-".into()
787	        } else {
788	            arg.to_value_os().to_string_lossy()
789	        };
790	        completions.extend(
791	            shorts_and_visible_aliases(cmd, disabled)
792	                .into_iter()
793	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
794	        );
795	    } else if arg.is_stdio() {
796	        // HACK: Assuming knowledge of is_stdio
797	        let dash_or_arg = if arg.is_empty() {
798	            "-".into()
799	        } else {
800	            arg.to_value_os().to_string_lossy()
801	        };
802	        completions.extend(
803	            shorts_and_visible_aliases(cmd, disabled)
804	                .into_iter()
805	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
806	        );
807	
808	        completions.extend(longs_and_visible_aliases(cmd, disabled));
809	        completions.extend(hidden_longs_aliases(cmd, disabled));
810	    } else if arg.is_escape() {
811	        // HACK: Assuming knowledge of is_escape
812	        completions.extend(longs_and_visible_aliases(cmd, disabled));
813	        completions.extend(hidden_longs_aliases(cmd, disabled));
814	    } else if let Some((flag, value)) = arg.to_long() {
815	        if let Ok(flag) = flag {
816	            if let Some(value) = value {
817	                let opt = cmd.get_arguments().find(|a| {
818	                    a.get_long_and_visible_aliases()
819	                        .is_some_and(|longs| longs.into_iter().any(|long| long == flag))
820	                });
821	                if let Some(arg) = opt {
822	                    if !disabled.contains(arg.get_id()) {
823	                        if let Ok(values) =
824	                            complete_segment_value(value, arg, 0, &[], 0, current_dir)
825	                        {
826	                            completions.extend(
827	                                values
828	                                    .into_iter()
829	                                    .map(|comp| comp.add_prefix(format!("--{flag}="))),
830	                            );
831	                        }
832	                    }
833	                }
834	            } else {
835	                completions.extend(
836	                    longs_and_visible_aliases(cmd, disabled)
837	                        .into_iter()
838	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
839	                );
840	                completions.extend(
841	                    hidden_longs_aliases(cmd, disabled)
842	                        .into_iter()
843	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
844	                );
845	            }
846	        }
847	    } else if let Some(short) = arg.to_short() {
848	        if !short.is_negative_number() {
849	            // Find the first takes_values option.
850	            let (leading_flags, takes_value_opt, mut short, _) = parse_shortflags(cmd, short);
851	
852	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
853	            if let Some(opt) = takes_value_opt {
854	                if !disabled.contains(opt.get_id()) {
855	                    let mut peek_short = short.clone();
856	                    let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
857	                        short.next_flag();
858	                        true
859	                    } else {
860	                        false
861	                    };
862	
863	                    let value = short.next_value_os().unwrap_or(OsStr::new(""));
864	                    if let Ok(values) = complete_segment_value(value, opt, 0, &[], 0, current_dir) {
865	                        completions.extend(values.into_iter().map(|comp| {
866	                            let sep = if has_equal { "=" } else { "" };
867	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
868	                        }));
869	                    }
870	                }
871	            } else {
872	                completions.extend(
873	                    shorts_and_visible_aliases(cmd, disabled)
874	                        .into_iter()
875	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
876	                );
877	            }
878	        }
879	    }
880	    debug!("complete_option: completions={completions:?}");
881	    completions
882	}
