884	fn complete_arg_value(
885	    value: Result<&str, &OsStr>,
886	    arg: &clap::Arg,
887	    current_dir: Option<&std::path::Path>,
888	    arg_index: usize,
889	) -> Vec<CompletionCandidate> {
890	    let mut values = Vec::new();
891	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
892	
893	    let (prefix, value) =
894	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
895	
896	    let value_os = match value {
897	        Ok(value) => OsStr::new(value),
898	        Err(value_os) => value_os,
899	    };
900	
901	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
902	        values.extend(completer.complete_at(arg_index, value_os));
903	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
904	        values.extend(complete_value_candidates(
905	            value_os,
906	            completer.value_candidates(),
907	        ));
908	    } else if let Some(possible_values) = possible_values(arg) {
909	        if let Ok(value) = value {
910	            values.extend(complete_candidates_str(
911	                value,
912	                possible_value_candidates(possible_values),
913	            ));
914	        }
915	    } else {
916	        match arg.get_value_hint() {
917	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
918	                // Should not complete
919	            }
920	            clap::ValueHint::AnyPath => {
921	                values.extend(complete_path(value_os, current_dir, &|_| true));
922	            }
923	            clap::ValueHint::FilePath => {
924	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
925	            }
926	            clap::ValueHint::DirPath => {
927	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
928	            }
929	            clap::ValueHint::ExecutablePath => {
930	                use is_executable::IsExecutable;
931	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
932	            }
933	            clap::ValueHint::CommandName
934	            | clap::ValueHint::CommandString
935	            | clap::ValueHint::CommandWithArguments
936	            | clap::ValueHint::Username
937	            | clap::ValueHint::Hostname
938	            | clap::ValueHint::Url
939	            | clap::ValueHint::EmailAddress => {
940	                // No completion implementation
941	            }
942	            _ => {
943	                // Safe-ish fallback
944	                values.extend(complete_path(value_os, current_dir, &|_| true));
945	            }
946	        }
947	
948	        values.sort();
949	    }
950	
951	    if let Some(prefix) = prefix {
952	        values = values
953	            .into_iter()
954	            .map(|comp| comp.add_prefix(prefix))
955	            .collect();
956	    }
957	    values = values
958	        .into_iter()
959	        .map(|comp| {
960	            if comp.get_tag().is_some() {
961	                comp
962	            } else {
963	                comp.tag(Some(arg.to_string().into()))
964	            }
965	        })
966	        .collect();
967	
968	    debug!("complete_arg_value: values={values:?}");
969	    values
970	}
