972	fn rsplit_delimiter<'s, 'o>(
973	    value: Result<&'s str, &'o OsStr>,
974	    delimiter: Option<char>,
975	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
976	    let delimiter = delimiter?;
977	    let value = value.ok()?;
978	    let pos = value.rfind(delimiter)?;
979	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
980	    Some((Some(prefix), Ok(value)))
981	}
