1013	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
1014	    debug!(
1015	        "complete_subcommand: cmd={:?}, value={:?}",
1016	        cmd.get_name(),
1017	        value
1018	    );
1019	
1020	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
1021	        .into_iter()
1022	        .filter(|x| x.get_value().starts_with(value))
1023	        .collect();
1024	    if cmd.is_allow_external_subcommands_set() {
1025	        let external_completer = cmd.get::<SubcommandCandidates>();
1026	        if let Some(completer) = external_completer {
1027	            scs.extend(complete_value_candidates_str(
1028	                value,
1029	                completer.value_candidates(),
1030	            ));
1031	        }
1032	    }
1033	
1034	    scs.sort();
1035	    scs.dedup();
1036	    scs
1037	}
