1165	/// Parse the short flags and find the first `takes_values` option.
1166	///
1167	/// The returned bool is `true` only when every scanned cluster member was a
1168	/// recognized option. Anything after the first value-taking option is the
1169	/// option's value and therefore not scanned; invalid UTF-8 and unknown short
1170	/// characters make the result `false`.
1171	fn parse_shortflags<'c, 's>(
1172	    cmd: &'c clap::Command,
1173	    mut short: clap_lex::ShortFlags<'s>,
1174	) -> (
1175	    String,
1176	    Option<&'c clap::Arg>,
1177	    clap_lex::ShortFlags<'s>,
1178	    bool,
1179	) {
1180	    let takes_value_opt;
1181	    let mut leading_flags = String::new();
1182	    let mut cluster_valid = true;
1183	    // Find the first takes_values option.
1184	    loop {
1185	        match short.next_flag() {
1186	            Some(Ok(opt)) => {
1187	                leading_flags.push(opt);
1188	                let found = cmd.get_arguments().find(|a| {
1189	                    let shorts = a.get_short_and_visible_aliases();
1190	                    let is_find = shorts.map(|v| {
1191	                        let mut iter = v.into_iter();
1192	                        let c = iter.find(|c| *c == opt);
1193	                        c.is_some()
1194	                    });
1195	                    is_find.unwrap_or(false)
1196	                });
1197	                if let Some(opt) = found {
1198	                    if opt.get_num_args().expect("built").takes_values() {
1199	                        takes_value_opt = Some(opt);
1200	                        break;
1201	                    }
1202	                } else {
1203	                    cluster_valid = false;
1204	                }
1205	            }
1206	            Some(Err(_)) => {
1207	                cluster_valid = false;
1208	                takes_value_opt = None;
1209	                break;
1210	            }
1211	            None => {
1212	                takes_value_opt = None;
1213	                break;
1214	            }
1215	        }
1216	    }
1217	
1218	    (leading_flags, takes_value_opt, short, cluster_valid)
1219	}
1220	
1221	/// Parse the positional arguments. Return the new state and the new positional index.
1222	fn parse_positional<'a>(
1223	    cmd: &clap::Command,
1224	    pos_index: usize,
1225	    is_escaped: bool,
1226	    state: ParseState<'a>,
1227	) -> (ParseState<'a>, usize) {
1228	    let pos_arg = cmd
1229	        .get_positionals()
1230	        .find(|p| p.get_index() == Some(pos_index));
1231	    let num_args = pos_arg
1232	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
1233	        .unwrap_or(1);
1234	
1235	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
1236	        if num_args > 1 {
1237	            (ParseState::Pos((pos_index, 1)), pos_index)
1238	        } else {
1239	            if is_escaped {
1240	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
1241	            } else {
1242	                (ParseState::ValueDone, pos_index + 1)
1243	            }
1244	        }
1245	    };
1246	    match state {
1247	        ParseState::ValueDone => {
1248	            update_state_with_new_positional(pos_index)
1249	        },
1250	        ParseState::Pos((prev_pos_index, num_arg)) => {
1251	            if prev_pos_index == pos_index {
1252	                if num_arg + 1 < num_args {
1253	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
1254	                } else {
1255	                    if is_escaped {
1256	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
1257	                    } else {
1258	                        (ParseState::ValueDone, pos_index + 1)
1259	                    }
1260	                }
1261	            } else {
1262	                update_state_with_new_positional(pos_index)
1263	            }
1264	        }
1265	        ParseState::Opt(..) => unreachable!(
1266	            "This branch won't be hit,
1267	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
1268	        ),
1269	    }
1270	}
1271	
1272	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
1273	    cmd.get_positionals()
1274	        .find(|a| a.get_index() == Some(pos_index))
1275	        .map(|p| p.is_allow_hyphen_values_set())
1276	        .unwrap_or(false)
1277	}
1278	
1279	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
1280	    let val = arg.to_value_os();
1281	    if val.starts_with("-") {
1282	        if let ParseState::Opt(state) = state {
1283	            return state.opt.is_allow_hyphen_values_set();
1284	        }
1285	    }
1286	
1287	    false
1288	}
1289	
1290	/// Arguments that must not be offered because they conflict with an explicitly
1291	/// present option. The present options themselves are never disabled.
1292	fn gather_disabled_args(cmd: &clap::Command, explicit: &HashSet<Id>) -> HashSet<Id> {
1293	    let mut disabled = HashSet::new();
1294	    if explicit.is_empty() {
1295	        return disabled;
1296	    }
1297	    for arg in cmd.get_arguments() {
1298	        if explicit.contains(arg.get_id()) {
1299	            // A present option hides everything it conflicts with ...
1300	            for id in arg_direct_conflicts(cmd, arg) {
1301	                if !explicit.contains(&id) {
1302	                    disabled.insert(id);
1303	                }
1304	            }
1305	        } else {
1306	            // ... and is hidden when either side declares the conflict.
1307	            if arg_direct_conflicts(cmd, arg)
1308	                .iter()
1309	                .any(|id| explicit.contains(id))
1310	            {
1311	                disabled.insert(arg.get_id().clone());
1312	            }
1313	        }
1314	    }
1315	    disabled
1316	}
1317	
1318	/// Conflict partners of `arg`, following the same rules as clap's parser:
1319	/// - the argument's own `conflicts_with` / `conflicts_with_all`
1320	/// - `conflicts_with` / `conflicts_with_all` of every group the argument belongs to
1321	/// - the other members of non-`multiple` groups
1322	///
1323	/// Group ids are expanded to their argument members.
1324	/// `overrides_with` relationships are intentionally not considered.
1325	fn arg_direct_conflicts(cmd: &clap::Command, arg: &clap::Arg) -> HashSet<Id> {
1326	    let mut conflicts = arg
1327	        .get_conflicts_with()
1328	        .map(ToOwned::to_owned)
1329	        .collect::<HashSet<_>>();
1330	    for group in cmd.get_groups() {
1331	        let members = unroll_group(cmd, group.get_id());
1332	        if !members.iter().any(|m| m == arg.get_id()) {
1333	            continue;
1334	        }
1335	        conflicts.extend(group.get_conflicts_with().map(ToOwned::to_owned));
1336	        if !group.is_multiple_set() {
1337	            conflicts.extend(members.into_iter().filter(|m| m != arg.get_id()));
1338	        }
1339	    }
1340	    conflicts
1341	        .iter()
1342	        .flat_map(|id| unroll_group(cmd, id))
1343	        .collect()
1344	}
1345	
1346	/// Resolve an argument or group id to its argument members.
1347	/// Unknown ids resolve to themselves.
1348	fn unroll_group(cmd: &clap::Command, id: &Id) -> Vec<Id> {
1349	    let mut pending = vec![id.clone()];
1350	    let mut args = Vec::new();
1351	    while let Some(id) = pending.pop() {
1352	        if cmd.get_arguments().any(|a| a.get_id() == &id) {
1353	            if !args.contains(&id) {
1354	                args.push(id);
1355	            }
1356	        } else if let Some(group) = cmd.get_groups().find(|g| g.get_id() == &id) {
1357	            pending.extend(group.get_args().map(ToOwned::to_owned));
1358	        } else if !args.contains(&id) {
1359	            args.push(id);
1360	        }
1361	    }
1362	    args
1363	}
