use clap::Command;

fn build() -> Command {
    Command::new("t")
        .arg(
            clap::Arg::new("tag")
                .long("tag").visible_alias("label").short('t')
                .num_args(1..=3)
                .value_parser(["red", "green", "blue"])
                .value_delimiter(',')
                .value_terminator(";"),
        )
        .arg(
            clap::Arg::new("raw")
                .long("raw").action(clap::ArgAction::SetTrue).conflicts_with("tag"),
        )
        .arg(clap::Arg::new("path").value_parser(["src", "dst"]).value_hint(clap::ValueHint::AnyPath))
}

fn run(line: &str, dir: Option<&std::path::Path>) {
    let mut raw: Vec<std::ffi::OsString> = vec!["t".into()];
    let (prior, _) = line.split_once("[TAB]").unwrap();
    raw.extend(prior.split_whitespace().map(Into::into));
    if prior.ends_with(char::is_whitespace) { raw.push("".into()); }
    let idx = raw.len() - 1;
    let mut cmd = build();
    let out = match clap_complete::engine::complete(&mut cmd, raw, idx, dir) {
        Ok(cs) => cs.into_iter().map(|c| c.get_value().to_string_lossy().into_owned()).collect::<Vec<_>>().join("\n"),
        Err(e) => format!("ERR: {e}"),
    };
    println!("### {line}\n{out}\n");
}

fn main() {
    run("--tag=red, [TAB]", None);
    run("--label=red, [TAB]", None);
    run("-tred, [TAB]", None);
    run("-t=red, [TAB]", None);
    run("--tag red, [TAB]", None);
    run("--tag=red,g[TAB]", None);
    run("--tag=red,r[TAB]", None);
    run("--tag red ; [TAB]", None);
    run("--tag red ;[TAB]", None);
    run("--tag red ; -- [TAB]", None);
    run("--tag red ; -- s[TAB]", None);
    run("--tag red green ; [TAB]", None);
    run("--tag=red,green ; [TAB]", None);
    run("--tag ; [TAB]", None);
    run("--tag=red, ; [TAB]", None);
    run("--tag red ; ; [TAB]", None);
    run("--tag red; [TAB]", None);
    run("--tag=red; [TAB]", None);
    run("--tag=red ; ;x[TAB]", None);
    run("--tag=red ; x[TAB]", None);
    run("--tag=red,green,blue ; [TAB]", None);
    run("--tag=red,green,b[TAB]", None);
    run("--tag=red,green,blue [TAB]", None);
    run("--tag=red,green,blue,[TAB]", None);
    run("--tag=red,red [TAB]", None);
}
EOF
