        Ok(cs)=>cs.into_iter().map(|c|c.get_value().to_string_lossy().into_owned()).collect::<Vec<_>>().join("\n"),
        Err(e)=>format!("ERR: {e}"),
    };
    println!("### {line}\n{o}\n");
}
